        allowMove = true; maxWorld = 3; maxSave = 2; maxProfile = 4; quits = worldFetches = saveModeCalls = 0;
        moreWorlds = moreSaves = moreProfiles = 0; chosenWorld = chosenSave = chosenProfile = 0;
